    /// `DATUM_REFERENCE_COMPARTMENT` — strict AP242 constructor.
    pub fn add_datum_reference_compartment(
        &mut self,
        name: String,
        description: Option<String>,
        of_shape: ProductDefinitionShapeRef,
        product_definitional: Logical,
        base: DatumOrCommonDatumRef,
        modifiers: Option<Vec<DatumReferenceModifierRef>>,
    ) -> Result<DatumReferenceCompartmentId, AuthorError> {
        check_product_definition_shape_ref(&self.model, &of_shape)?;
        check_datum_or_common_datum_ref(&self.model, &base)?;
        if let Some(x) = &modifiers {
            if x.len() < 1 {
                return Err(AuthorError::Cardinality {
                    entity: "DATUM_REFERENCE_COMPARTMENT",
                    attribute: "modifiers",
                    got: x.len(),
                    min: 1,
                    max: None,
                });
            }
        }
        if let Some(x) = &modifiers {
            for e0 in x {
                check_datum_reference_modifier_ref(&self.model, e0)?;
            }
        }
        Ok(DatumReferenceCompartmentId(
            self.model
                .datum_reference_compartment_arena
                .push(DatumReferenceCompartment {
                    name,
                    description,
                    of_shape,
                    product_definitional,
                    base,
                    modifiers,
                }),
        ))
    }

