fn check_edge_ref(model: &StepModel, r: &EdgeRef) -> Result<(), AuthorError> {
    match r {
        EdgeRef::Edge(i) => {
            if i.0 >= model.edge_arena.items.len() {
                return Err(AuthorError::DanglingRef { entity: "EDGE" });
            }
        }
        EdgeRef::EdgeCurve(i) => {
            if i.0 >= model.edge_curve_arena.items.len() {
                return Err(AuthorError::DanglingRef {
                    entity: "EDGE_CURVE",
                });
            }
        }
        EdgeRef::OrientedEdge(i) => {
            if i.0 >= model.oriented_edge_arena.items.len() {
                return Err(AuthorError::DanglingRef {
                    entity: "ORIENTED_EDGE",
                });
            }
        }
        EdgeRef::Complex(i) => {
            if i.0 >= model.complex_unit_arena.items.len() {
                return Err(AuthorError::DanglingRef { entity: "COMPLEX" });
            }
        }
    }
    Ok(())
}
