fn check_transformation_ref(model: &StepModel, r: &TransformationRef) -> Result<(), AuthorError> {
    match r {
        TransformationRef::FunctionallyDefinedTransformation(i) => {
            if i.0 >= model.functionally_defined_transformation_arena.items.len() {
                return Err(AuthorError::DanglingRef {
                    entity: "FUNCTIONALLY_DEFINED_TRANSFORMATION",
                });
            }
        }
        TransformationRef::ItemDefinedTransformation(i) => {
            if i.0 >= model.item_defined_transformation_arena.items.len() {
                return Err(AuthorError::DanglingRef {
                    entity: "ITEM_DEFINED_TRANSFORMATION",
                });
            }
        }
        TransformationRef::ListItemDefinedTransformation(v) => {
            for e in v {
                check_item_defined_transformation_ref(model, e)?;
            }
        }
        TransformationRef::SetItemDefinedTransformation(v) => {
            for e in v {
                check_item_defined_transformation_ref(model, e)?;
            }
        }
        TransformationRef::Complex(i) => {
            if i.0 >= model.complex_unit_arena.items.len() {
                return Err(AuthorError::DanglingRef { entity: "COMPLEX" });
            }
        }
    }
    Ok(())
}
fn check_trimming_select_ref(model: &StepModel, r: &TrimmingSelectRef) -> Result<(), AuthorError> {
    match r {
        TrimmingSelectRef::ApllPoint(_) => {
            return Err(AuthorError::NotAp242 {
                entity: "APLL_POINT",
            });
        }
        TrimmingSelectRef::ApllPointWithSurface(_) => {
            return Err(AuthorError::NotAp242 {
                entity: "APLL_POINT_WITH_SURFACE",
            });
        }
        TrimmingSelectRef::CartesianPoint(i) => {
            if i.0 >= model.cartesian_point_arena.items.len() {
                return Err(AuthorError::DanglingRef {
                    entity: "CARTESIAN_POINT",
                });
            }
        }
        TrimmingSelectRef::ParameterValue(_) => {}
    }
    Ok(())
}
